class Solution {
public:
    int countTriplets(vector<int>& arr) {
        unordered_map<int, pair<int,int>> mp;
        mp[0] = {1, 0};
        int prefix = 0;
        int ans = 0;
        int n = arr.size();
        for (int r = 1; r <= n; r++) {
            prefix ^= arr[r - 1];
            auto it = mp.find(prefix);
            if (it != mp.end()) {
                ans += it->second.first * (r - 1) - it->second.second;
            }
            mp[prefix].first++;
            mp[prefix].second += r;
        }
        return ans;
    }
};
